import sys; sys.path.insert(0,'iter_0/candidate_5/scratch/s')
from screen import *
L=LL(0.9); Si=S[NR:]
def predp(logpi,lam,lapse,gy):
    pi=logpi-logsumexp(logpi)
    prior=np.concatenate([np.full(NR,np.log(lam)-np.log(NR)),np.log(1-lam)+pi])
    lp=L+prior; lp-=logsumexp(lp,axis=1,keepdims=True); q=np.exp(lp)@M
    return np.clip((1-lapse)*q[si,tg]+lapse*gy,1e-6,1-1e-6)
forms={'erlang':lambda s,ls: np.log(s)-s/np.exp(ls),'expon':lambda s,ls:-s/np.exp(ls),'power':lambda s,g:-g*np.log(s)}
for k,f in forms.items():
    best=None
    for x0 in ([1.0],[2.5],[4.0]) if k!='power' else ([0.],[0.3]):
        r=minimize(lambda t: nll(predp(f(Si,t[3]),expit(t[0]),expit(t[1]),expit(t[2]))),[-0.7,-5,5,x0[0]],method='Nelder-Mead',options=dict(maxiter=1000))
        if best is None or r.fun<best.fun: best=r
    print(k,round(best.fun,2),best.x.round(3),flush=True)
